// Les défenses en montagne n'ont pas de point d'apparition : les vagues viennent de tout autour.

const XP = (lv, k = 1) => Math.round(7.9 * lv * lv * k / 10) * 10;
const OR = (lv, k = 1) => Math.round(0.79 * lv * lv * k / 5) * 5;

const SIDES = {
  l: { p: 'l', f: 'lumiere', env4: 'a4_aldren', env: 'a5_aldren', cap: 'a5_helis', ennemi: 'a5_lame_ombre', gardePropre: 'a5_garde_aube',
    gardeEnnemi: 'a5_garde_ombre', banniere: 'a5_banniere_soleil', convoi: ['a5_convoi_ouest', 'a5_convoi_soleil'], poste: 'a5_poste_nuit_coeur',
    prev: 'a4_l_ce_que_le_sable_a_vu' },
  o: { p: 'o', f: 'ombre', env4: 'a4_vesper', env: 'a5_vesper', cap: 'a5_sarn', ennemi: 'a5_lame_aube', gardePropre: 'a5_garde_ombre',
    gardeEnnemi: 'a5_garde_aube', banniere: 'a5_banniere_nuit', convoi: ['a5_convoi_est', 'a5_convoi_nuit'], poste: 'a5_poste_soleil_coeur',
    prev: 'a4_o_ce_que_le_sable_a_vu' },
};
const duo = build => [build(SIDES.l), build(SIDES.o)];
const T = (S, l, o) => (S.p === 'l' ? l : o);
const id = (S, n) => `a5_${S.p}_${n}`;
const retour = S => T(S, ['Revenir voir Aldren', 'Return to Aldren'], ['Revenir voir Vesper', 'Return to Vesper']);

